// Measuring a simple function
function slowCalculation(n) {
  let result = 0;
  for (let i = 0; i < n; i++) {
    result += Math.sqrt(i);
  }
  return result;
}

const result = timeTaken(slowCalculation, 1000000);
// Console output: timeTaken: 45.123ms
// Returns: calculated result

